/**
 * The Diplomat, with second-source corroboration merged in (DECISIONS D-018).
 * base.ts holds the authored content; corroboration.ts is generated by scripts/cross-check.ts.
 */
import base from "./base";
import { corroboration, checkedOn } from "./corroboration";
import type { ShowContent } from "../../src/spoiler/types";

const content: ShowContent = {
  ...base,
  characters: base.characters.map((c) => ({
    ...c,
    facts: c.facts.map((f) => {
      const url = corroboration[f.text];
      return url ? { ...f, source: [...f.source, { kind: "press" as const, ref: url, checkedBy: "automated cross-check", checkedOn }] } : f;
    }),
  })),
};

export default content;
